  data = {'action': 'get_tasking', 'tasking_size': -1}
  tasking_data = self.postMessageAndRetrieveResponse(data)
  for task in tasking_data['tasks']:
    t = {
      'task_id': task['id'],
      'command': task['command'],
      'parameters': task['parameters'],
      ...
    }
    self.taskings.append(t)

